import { Fragment, useMemo, type ReactNode } from 'react';
import { getComponentMarkdown, isFigmaSourcedMarkdown } from '../pages/ComponentPage/componentMarkdown';
import './MarkdownView.scss';

/* ------------------------------------------------------------------
 * Minimal, dependency-free Markdown renderer for the component docs
 * generated by scripts/docs-generator.cjs. Builds React elements
 * directly (no innerHTML), supporting: headings, paragraphs, fenced
 * code, GFM tables, lists, blockquotes, GitHub alerts ([!NOTE] etc.),
 * horizontal rules and inline code / bold / italic / links.
 * ------------------------------------------------------------------ */

type AlertKind = 'note' | 'tip' | 'important' | 'warning' | 'caution';

type Block =
  | { kind: 'heading'; level: number; text: string }
  | { kind: 'paragraph'; text: string }
  | { kind: 'code'; lang: string; code: string }
  | { kind: 'table'; header: string[]; rows: string[][] }
  | { kind: 'list'; ordered: boolean; items: string[] }
  | { kind: 'quote'; alert?: AlertKind; lines: string[] }
  | { kind: 'rule' };

export function slugifyHeading(text: string): string {
  return `md-${text.toLowerCase().replace(/<[^>]+>/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')}`;
}

function splitTableRow(line: string): string[] {
  const trimmed = line.trim().replace(/^\|/, '').replace(/\|$/, '');
  const cells: string[] = [];
  let current = '';
  for (let i = 0; i < trimmed.length; i++) {
    const ch = trimmed[i];
    if (ch === '\\' && trimmed[i + 1] === '|') {
      current += '|';
      i++;
    } else if (ch === '|') {
      cells.push(current.trim());
      current = '';
    } else {
      current += ch;
    }
  }
  cells.push(current.trim());
  return cells;
}

function parseBlocks(markdown: string): Block[] {
  const lines = markdown.replace(/\r\n/g, '\n').split('\n');
  const blocks: Block[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();

    if (!trimmed || /^<!--.*-->$/.test(trimmed)) {
      i++;
      continue;
    }

    const fence = trimmed.match(/^```(\w*)/);
    if (fence) {
      const code: string[] = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith('```')) code.push(lines[i++]);
      i++;
      blocks.push({ kind: 'code', lang: fence[1] || 'text', code: code.join('\n') });
      continue;
    }

    const heading = trimmed.match(/^(#{1,6})\s+(.*)$/);
    if (heading) {
      blocks.push({ kind: 'heading', level: heading[1].length, text: heading[2] });
      i++;
      continue;
    }

    if (/^(-{3,}|\*{3,})$/.test(trimmed)) {
      blocks.push({ kind: 'rule' });
      i++;
      continue;
    }

    if (trimmed.startsWith('|') && i + 1 < lines.length && /^\|?\s*:?-{3,}/.test(lines[i + 1].trim())) {
      const header = splitTableRow(trimmed);
      const rows: string[][] = [];
      i += 2;
      while (i < lines.length && lines[i].trim().startsWith('|')) rows.push(splitTableRow(lines[i++]));
      blocks.push({ kind: 'table', header, rows });
      continue;
    }

    if (trimmed.startsWith('>')) {
      const quoteLines: string[] = [];
      while (i < lines.length && lines[i].trim().startsWith('>')) {
        quoteLines.push(lines[i++].trim().replace(/^>\s?/, ''));
      }
      const alertMatch = quoteLines[0]?.match(/^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\]$/i);
      blocks.push(
        alertMatch
          ? { kind: 'quote', alert: alertMatch[1].toLowerCase() as AlertKind, lines: quoteLines.slice(1) }
          : { kind: 'quote', lines: quoteLines }
      );
      continue;
    }

    const listMatch = trimmed.match(/^([-*]|\d+\.)\s+/);
    if (listMatch) {
      const ordered = /\d/.test(listMatch[1]);
      const items: string[] = [];
      while (i < lines.length && /^\s*([-*]|\d+\.)\s+/.test(lines[i])) {
        items.push(lines[i++].trim().replace(/^([-*]|\d+\.)\s+/, ''));
      }
      blocks.push({ kind: 'list', ordered, items });
      continue;
    }

    const para: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() &&
      !/^(#{1,6}\s|```|>|\||[-*]\s|\d+\.\s)/.test(lines[i].trim())
    ) {
      para.push(lines[i++].trim());
    }
    blocks.push({ kind: 'paragraph', text: para.join(' ') });
  }

  return blocks;
}

const INLINE_PATTERN = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)\s]+\))|((?<![\w])_[^_]+_(?![\w]))|((?<![\w*])\*[^*\s][^*]*\*(?![\w*]))|(https?:\/\/[^\s|)]+)/g;

function isSafeUrl(url: string): boolean {
  return /^(https?:|mailto:|#|\/)/i.test(url);
}

function renderInline(text: string, keyPrefix = 'i'): ReactNode[] {
  const nodes: ReactNode[] = [];
  let lastIndex = 0;
  let index = 0;

  for (const match of text.matchAll(INLINE_PATTERN)) {
    const [token] = match;
    const start = match.index ?? 0;
    if (start > lastIndex) nodes.push(text.slice(lastIndex, start));
    const key = `${keyPrefix}-${index++}`;

    if (token.startsWith('`')) {
      nodes.push(<code key={key}>{token.slice(1, -1)}</code>);
    } else if (token.startsWith('**')) {
      nodes.push(<strong key={key}>{renderInline(token.slice(2, -2), key)}</strong>);
    } else if (token.startsWith('[')) {
      const link = token.match(/^\[([^\]]+)\]\(([^)\s]+)\)$/);
      if (link && isSafeUrl(link[2])) {
        nodes.push(
          <a key={key} href={link[2]} target={link[2].startsWith('#') ? undefined : '_blank'} rel="noopener noreferrer">
            {renderInline(link[1], key)}
          </a>
        );
      } else {
        nodes.push(token);
      }
    } else if (token.startsWith('http')) {
      nodes.push(
        <a key={key} href={token} target="_blank" rel="noopener noreferrer">
          {token}
        </a>
      );
    } else {
      nodes.push(<em key={key}>{renderInline(token.slice(1, -1), key)}</em>);
    }
    lastIndex = start + token.length;
  }

  if (lastIndex < text.length) nodes.push(text.slice(lastIndex));
  return nodes;
}

const ALERT_TITLES: Record<AlertKind, string> = {
  note: 'Note',
  tip: 'Status',
  important: 'Changes detected',
  warning: 'Warning',
  caution: 'Caution'
};

function renderBlock(block: Block, key: number): ReactNode {
  switch (block.kind) {
    case 'heading': {
      const id = slugifyHeading(block.text);
      const content = renderInline(block.text, `h${key}`);
      if (block.level === 1) return <h1 key={key} id={id}>{content}</h1>;
      if (block.level === 2) return <h2 key={key} id={id}>{content}</h2>;
      if (block.level === 3) return <h3 key={key} id={id}>{content}</h3>;
      return <h4 key={key} id={id}>{content}</h4>;
    }
    case 'paragraph':
      return <p key={key}>{renderInline(block.text, `p${key}`)}</p>;
    case 'code':
      return (
        <div key={key} className="md-code">
          <span className="md-code-lang">{block.lang}</span>
          <pre><code>{block.code}</code></pre>
        </div>
      );
    case 'table':
      return (
        <div key={key} className="md-table-wrap">
          <table>
            <thead>
              <tr>{block.header.map((cell, c) => <th key={c}>{renderInline(cell, `th${key}-${c}`)}</th>)}</tr>
            </thead>
            <tbody>
              {block.rows.map((row, r) => (
                <tr key={r}>
                  {row.map((cell, c) => <td key={c}>{renderInline(cell, `td${key}-${r}-${c}`)}</td>)}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    case 'list': {
      const items = block.items.map((item, n) => <li key={n}>{renderInline(item, `li${key}-${n}`)}</li>);
      return block.ordered ? <ol key={key}>{items}</ol> : <ul key={key}>{items}</ul>;
    }
    case 'quote':
      if (block.alert) {
        return (
          <div key={key} className={`md-alert md-alert--${block.alert}`} role="note">
            <span className="md-alert-title">{ALERT_TITLES[block.alert]}</span>
            {block.lines.map((line, n) => <p key={n}>{renderInline(line, `q${key}-${n}`)}</p>)}
          </div>
        );
      }
      return (
        <blockquote key={key}>
          {block.lines.map((line, n) => <p key={n}>{renderInline(line, `q${key}-${n}`)}</p>)}
        </blockquote>
      );
    case 'rule':
      return <hr key={key} />;
    default:
      return null;
  }
}

export function MarkdownView({ markdown, hideTitle = false }: { markdown: string; hideTitle?: boolean }) {
  const blocks = useMemo(() => {
    const parsed = parseBlocks(markdown);
    return hideTitle ? parsed.filter((b, n) => !(n === 0 && b.kind === 'heading' && b.level === 1)) : parsed;
  }, [markdown, hideTitle]);

  return (
    <div className="md-view">
      {blocks.map((block, n) => <Fragment key={n}>{renderBlock(block, n)}</Fragment>)}
    </div>
  );
}

/**
 * Docs-page section that renders src/components/<slug>/<slug>.md.
 * Re-renders live via Vite HMR whenever the Figma sync engine updates the file.
 */
export function ComponentMarkdownSection({ slug, title }: { slug: string; title: string }) {
  const markdown = getComponentMarkdown(slug);
  const sourcePath = `src/components/${slug}/${slug}.md`;

  return (
    <section className="docs-section md-docs-section" id="component-docs">
      <div className="docs-section-heading md-docs-heading">
        <div>
          <h2>Documentation</h2>
          <p>
            Rendered from <code>{sourcePath}</code> — kept in sync with Figma automatically.
          </p>
        </div>
        {markdown && (
          <span className={`md-source-badge ${isFigmaSourcedMarkdown(markdown) ? 'md-source-badge--figma' : ''}`}>
            {isFigmaSourcedMarkdown(markdown) ? 'Synced from Figma' : 'Local baseline'}
          </span>
        )}
      </div>
      {markdown ? (
        <div className="md-docs-card">
          <MarkdownView markdown={markdown} hideTitle />
        </div>
      ) : (
        <div className="md-alert md-alert--note" role="note">
          <span className="md-alert-title">No documentation yet</span>
          <p>
            <code>{sourcePath}</code> has not been generated. Run <code>npm run sync:app-pages</code> or sync {title} from Figma.
          </p>
        </div>
      )}
    </section>
  );
}

